static void test_mul(void) {
    TEST_SUITE("p256_fe_mul — a * b mod p");

    for (int i = 0; i < NPAIRS; i++) {
        uint64_t a[4], b[4], out[4];
        uint8_t outb[32];
        p256_fe_frombytes(a, PAIRS[i].a);
        p256_fe_frombytes(b, PAIRS[i].b);
        p256_fe_mul(out, a, b);
        p256_fe_tobytes(outb, out);
        ASSERT_EQ("a*b mod p", 0, memcmp(outb, PAIRS[i].prod, 32));
    }

    uint64_t a[4], b[4];
    p256_fe_frombytes(a, PAIRS[0].a);
    p256_fe_frombytes(b, PAIRS[0].b);
    p256_fe_mul(a, a, b);
    uint8_t outb[32];
    p256_fe_tobytes(outb, a);
    ASSERT_EQ("a*b mod p, out aliases a", 0, memcmp(outb, PAIRS[0].prod, 32));
}

int main(void) {
    test_mul();
    test_summary();
    return 0;
}
